Which of the following are context free language?
A. {wi xj yk zl | i + k = j + l, where i, j, k, l ≥ 0}
B. {wi xj yk zl | i = j and k = l, where i, j, k, l ≥ 0}
C. {wi xj yk zl | i = j = k and k ≠ l, where i, j, k, l ≥ 0}
D. {wi xj yk zl | i = j = k + l, where i, j, k, l ≥ 0}
E. {wi xj yk zl | i = j = l and k ≠ l, where i, j, k, l ≥ 0}

Consider following C program:
#include<stdio.h>
int main() {
  int x[] = {2,4,6,8,10};
  int a,b=0, *y = x+4;
  for(a=0; a<=4; a++) {
    b = b + (*y - a) - *(y - a);
  }
  printf("%d\n", b);
  return 0;
}
What will be the output?

#include<iostream>
using namespace std;
void swap (int &x, int &y) { int temp = x; x = y; y = temp; }
int main() {
  int a = 5, b = 10;
  swap(a, b);
  cout << a << " " << b;
  return 0;
}
What will be the output of above code?

#include<stdio.h>
void main() {
  int arr[] = {1, 2, 3, 4, 5};
  int *p = arr;
  printf("%d", *p++);
  printf("%d", *(p+1));
}
Find the output of the above code?

What will be the output of the following C code?
#include<stdio.h>
void main() {
  int arr[5] = {10, 20, 30, 40, 50};
  int *p = (int*)(&arr + 1);
  printf("%d %d", *(arr+1), *(p-1));
}

